<?php $notifications=ess_inbox($pdo,$user);$unread=count(array_filter($notifications,fn($i)=>$i['state']==='Unread'));?>
<div class="ess-header"><button type="button" data-ess-theme aria-label="Switch light and dark mode">◐</button><details class="ess-bell"><summary aria-label="Notifications">♧ <span><?= $unread ?></span></summary><div><strong>Notifications</strong><?php $recent=array_slice(array_values(array_filter($notifications,fn($i)=>$i['state']!=='Archived')),0,5);foreach($recent as $item):?><a href="?page=<?=h($item['page'])?>"><?=h($item['title'])?><small><?=h($item['text'])?></small></a><?php endforeach;if(!$recent):?><p>No new notifications.</p><?php endif;?><a href="?page=inbox">Open inbox</a></div></details><a href="?page=profile"><?=h($user['name'])?></a></div>
